// Output 1: GET /v1 device request. Output 2: verdict (reading rejected).
const EXPECTED_KEYS = [
    "battery_v", "do_mg_l", "ph", "rssi", "salinity_ppt",
    "seq", "temp_c", "ts", "turbidity_ntu",
];
const base = String(env.get("LIMNOPULSE_API_URL") || "http://127.0.0.1:8000").replace(/\/+$/, "");
const tenant = String(env.get("LIMNOPULSE_TENANT") || "tnt_local_001");
const parts = String(msg.topic || "").split("/");
const reading = msg.payload;

const ctx = {
    base: base,
    tenant: tenant,
    device_id: parts.length === 5 && parts[4] === "readings" ? parts[3] : null,
    seq: reading && reading.seq !== undefined ? reading.seq : null,
    ts: reading && typeof reading.ts === "string" ? reading.ts : null,
    v1_pond_id: null,
    component_id: null,
    native: false,
    resolved_asset_id: null,
    expected_asset_id: null,
};
msg.e2e = ctx;

function verdict(ok, reason) {
    msg.payload = {
        device_id: ctx.device_id,
        seq: ctx.seq,
        ts: ctx.ts,
        v1_pond_id: ctx.v1_pond_id,
        resolved_asset_id: ctx.resolved_asset_id,
        expected_asset_id: ctx.expected_asset_id,
        ok: ok,
        reason: reason,
    };
    return [null, msg];
}

if (!ctx.device_id) {
    return verdict(false, "bad-topic");
}
const keys = Object.keys(reading || {}).sort();
if (keys.join(",") !== EXPECTED_KEYS.join(",")) {
    return verdict(false, "payload-keys-mismatch");
}
if (!ctx.ts || !Number.isFinite(Date.parse(ctx.ts))) {
    return verdict(false, "bad-ts");
}

msg.method = "GET";
msg.url = base + "/v1/tenants/" + encodeURIComponent(tenant) + "/devices/" + encodeURIComponent(ctx.device_id);
msg.headers = {
    "Accept": "application/json",
    "X-Dev-User-Sub": String(env.get("LIMNOPULSE_DEV_USER_SUB") || "local-user-001"),
    "X-Dev-User-Email": String(env.get("LIMNOPULSE_DEV_USER_EMAIL") || "local@example.test"),
};
msg.payload = undefined;
return [msg, null];

// Single output: verdict for a reading whose payload is not a JSON object.
const parts = String(msg.topic || "").split("/");
msg.payload = {
    device_id: parts.length === 5 ? parts[3] : null,
    seq: null,
    ts: null,
    v1_pond_id: null,
    resolved_asset_id: null,
    expected_asset_id: null,
    ok: false,
    reason: "payload-not-json-object",
};
return msg;

// Output 1: GET /v2 device components request. Output 2: verdict.
// Legacy devices: /v1 pond -> deterministic default component + expected asset.
// Native v2 devices (canonical dev_<32hex>, /v1 404): ctx.native = true.
// Deterministic IDs mirror the Python helpers:
//   asset_id_for_legacy_pond(t, p) = "ast_" + uuid5(NAMESPACE_URL, "limnopulse/v4/legacy-pond/{t}/{p}").hex
//   default_component_id_for_legacy_device(t, d) =
//       "cmp_" + uuid5(NAMESPACE_URL, "limnopulse/v4/legacy-device-component/{t}/{d}").hex
const ctx = msg.e2e;

function verdict(ok, reason) {
    msg.payload = {
        device_id: ctx.device_id,
        seq: ctx.seq,
        ts: ctx.ts,
        v1_pond_id: ctx.v1_pond_id,
        resolved_asset_id: ctx.resolved_asset_id,
        expected_asset_id: ctx.expected_asset_id,
        ok: ok,
        reason: reason,
    };
    return [null, msg];
}

function sha1(bytes) {
    const ml = bytes.length;
    const withPad = ((ml + 9 + 63) >> 6) << 6;
    const buf = new Uint8Array(withPad);
    buf.set(bytes);
    buf[ml] = 0x80;
    const bitLen = ml * 8;
    buf[withPad - 4] = (bitLen >>> 24) & 0xff;
    buf[withPad - 3] = (bitLen >>> 16) & 0xff;
    buf[withPad - 2] = (bitLen >>> 8) & 0xff;
    buf[withPad - 1] = bitLen & 0xff;
    let h0 = 0x67452301, h1 = 0xefcdab89, h2 = 0x98badcfe, h3 = 0x10325476, h4 = 0xc3d2e1f0;
    const w = new Array(80);
    for (let off = 0; off < withPad; off += 64) {
        for (let i = 0; i < 16; i++) {
            const j = off + i * 4;
            w[i] = ((buf[j] << 24) | (buf[j + 1] << 16) | (buf[j + 2] << 8) | buf[j + 3]) | 0;
        }
        for (let i = 16; i < 80; i++) {
            const x = w[i - 3] ^ w[i - 8] ^ w[i - 14] ^ w[i - 16];
            w[i] = (x << 1) | (x >>> 31);
        }
        let a = h0, b = h1, c = h2, d = h3, e = h4;
        for (let i = 0; i < 80; i++) {
            let f, k;
            if (i < 20) { f = (b & c) | (~b & d); k = 0x5a827999; }
            else if (i < 40) { f = b ^ c ^ d; k = 0x6ed9eba1; }
            else if (i < 60) { f = (b & c) | (b & d) | (c & d); k = 0x8f1bbcdc; }
            else { f = b ^ c ^ d; k = 0xca62c1d6; }
            const t = (((a << 5) | (a >>> 27)) + f + e + k + w[i]) | 0;
            e = d; d = c; c = (b << 30) | (b >>> 2); b = a; a = t;
        }
        h0 = (h0 + a) | 0; h1 = (h1 + b) | 0; h2 = (h2 + c) | 0; h3 = (h3 + d) | 0; h4 = (h4 + e) | 0;
    }
    const out = new Uint8Array(20);
    [h0, h1, h2, h3, h4].forEach(function (h, i) {
        out[i * 4] = (h >>> 24) & 0xff;
        out[i * 4 + 1] = (h >>> 16) & 0xff;
        out[i * 4 + 2] = (h >>> 8) & 0xff;
        out[i * 4 + 3] = h & 0xff;
    });
    return out;
}

function uuid5Hex(name) {
    // RFC 4122 NAMESPACE_URL 6ba7b811-9dad-11d1-80b4-00c04fd430c8
    const ns = Buffer.from("6ba7b8119dad11d180b400c04fd430c8", "hex");
    const digest = sha1(Buffer.concat([ns, Buffer.from(name, "utf8")]));
    const b = Array.from(digest.slice(0, 16));
    b[6] = (b[6] & 0x0f) | 0x50;
    b[8] = (b[8] & 0x3f) | 0x80;
    return b.map(function (x) { return (x < 16 ? "0" : "") + x.toString(16); }).join("");
}

// HTTP nodes return text (ret "txt") so a non-JSON body (e.g. a text/plain
// 500) never triggers Node-RED's JSON parse warning; parse it here instead.
// undefined = not JSON.
function parseBody(raw) {
    if (raw !== null && typeof raw === "object" && !Buffer.isBuffer(raw)) return raw;
    if (raw === undefined || raw === null) return undefined;
    try {
        return JSON.parse(Buffer.isBuffer(raw) ? raw.toString("utf8") : String(raw));
    } catch (e) {
        return undefined;
    }
}

function v2Request(path) {
    msg.method = "GET";
    msg.url = ctx.base + "/v2/tenants/" + encodeURIComponent(ctx.tenant) + path;
    msg.headers = {
        "Accept": "application/json",
        "X-Dev-User-Sub": String(env.get("LIMNOPULSE_DEV_USER_SUB") || "local-user-001"),
        "X-Dev-User-Email": String(env.get("LIMNOPULSE_DEV_USER_EMAIL") || "local@example.test"),
    };
    msg.payload = undefined;
    return [msg, null];
}

// Canonical v2 device ids; native v2 devices have no /v1 row (404 after M1-05).
const CANONICAL_DEVICE_ID = /^dev_[0-9a-f]{32}$/;
const body = parseBody(msg.payload);

if (msg.statusCode === 404 && CANONICAL_DEVICE_ID.test(ctx.device_id)) {
    // Native v2 device: resolve through all of its components instead of the
    // legacy default component; there is no /v1 pond to cross-check.
    ctx.native = true;
    return v2Request("/devices/" + encodeURIComponent(ctx.device_id) + "/components");
}
if (msg.statusCode === 404) {
    return verdict(false, "v1-device-not-found");
}
if (msg.statusCode !== 200 || !body || typeof body !== "object" || Array.isArray(body)) {
    return verdict(false, "v1-error-" + String(msg.statusCode));
}
if (!body.pond_id) {
    return verdict(false, "v1-device-without-pond");
}

ctx.native = false;
ctx.v1_pond_id = body.pond_id;
ctx.expected_asset_id = "ast_" + uuid5Hex("limnopulse/v4/legacy-pond/" + ctx.tenant + "/" + ctx.v1_pond_id);
ctx.component_id = "cmp_" + uuid5Hex("limnopulse/v4/legacy-device-component/" + ctx.tenant + "/" + ctx.device_id);

return v2Request("/devices/" + encodeURIComponent(ctx.device_id) + "/components");

// Output 1: GET /v2 deployments request. Output 2: verdict.
// Legacy devices: the deterministic default component must be listed.
// Native v2 devices (ctx.native): every component is a candidate; their
// deployments are walked one by one by resolve_deployment.js.
const ctx = msg.e2e;

function verdict(ok, reason) {
    msg.payload = {
        device_id: ctx.device_id,
        seq: ctx.seq,
        ts: ctx.ts,
        v1_pond_id: ctx.v1_pond_id,
        resolved_asset_id: ctx.resolved_asset_id,
        expected_asset_id: ctx.expected_asset_id,
        ok: ok,
        reason: reason,
    };
    return [null, msg];
}

// HTTP nodes return text; undefined = body is not JSON.
function parseBody(raw) {
    if (raw !== null && typeof raw === "object" && !Buffer.isBuffer(raw)) return raw;
    if (raw === undefined || raw === null) return undefined;
    try {
        return JSON.parse(Buffer.isBuffer(raw) ? raw.toString("utf8") : String(raw));
    } catch (e) {
        return undefined;
    }
}

// /v2 is "unavailable" when the route is not mounted (Starlette's default
// 404 body), the flag rejects it (501/503), or the API answers 404 with an
// explicit disabled marker. Any other non-200 is a real failure.
function v2Unavailable(status, body) {
    if (status === 501 || status === 503) return true;
    if (status !== 404) return false;
    const detail = body && typeof body === "object" ? body.detail : body;
    if (detail === "Not Found") return true;
    return typeof detail === "string" && /v2|disabled/i.test(detail);
}

function items(body, key) {
    if (Array.isArray(body)) return body;
    if (body && Array.isArray(body.items)) return body.items;
    if (body && Array.isArray(body[key])) return body[key];
    return null;
}

const body = parseBody(msg.payload);
if (v2Unavailable(msg.statusCode, body)) {
    return verdict(null, "v2-unavailable");
}
if (ctx.native && msg.statusCode === 404) {
    return verdict(false, "v2-native-device-not-found");
}
if (msg.statusCode !== 200) {
    return verdict(false, "v2-components-error-" + String(msg.statusCode));
}
const components = items(body, "components");
if (components === null) {
    return verdict(false, "v2-components-bad-body");
}
const ids = components
    .map(function (c) { return c && (c.component_id || c.id); })
    .filter(function (id) { return typeof id === "string" && id.length > 0; });

if (ctx.native) {
    if (ids.length === 0) {
        return verdict(false, "v2-native-no-components");
    }
    ctx.component_id = ids[0];
    ctx.pending_component_ids = ids.slice(1);
    ctx.native_matches = [];
} else if (ids.indexOf(ctx.component_id) === -1) {
    return verdict(false, "default-component-missing");
}

msg.method = "GET";
msg.url = ctx.base + "/v2/tenants/" + encodeURIComponent(ctx.tenant) +
    "/deployments?component_id=" + encodeURIComponent(ctx.component_id);
msg.headers = {
    "Accept": "application/json",
    "X-Dev-User-Sub": String(env.get("LIMNOPULSE_DEV_USER_SUB") || "local-user-001"),
    "X-Dev-User-Email": String(env.get("LIMNOPULSE_DEV_USER_EMAIL") || "local@example.test"),
};
msg.payload = undefined;
return [msg, null];

// Output 1: GET /v2 asset request. Output 2: verdict.
// Output 3: GET /v2 deployments for the next component (native devices only).
// Resolves the deployment whose half-open interval [started_at, ended_at)
// contains the reading ts (ended_at null = still open).
const ctx = msg.e2e;

function verdict(ok, reason) {
    msg.payload = {
        device_id: ctx.device_id,
        seq: ctx.seq,
        ts: ctx.ts,
        v1_pond_id: ctx.v1_pond_id,
        resolved_asset_id: ctx.resolved_asset_id,
        expected_asset_id: ctx.expected_asset_id,
        ok: ok,
        reason: reason,
    };
    return [null, msg, null];
}

// HTTP nodes return text; undefined = body is not JSON.
function parseBody(raw) {
    if (raw !== null && typeof raw === "object" && !Buffer.isBuffer(raw)) return raw;
    if (raw === undefined || raw === null) return undefined;
    try {
        return JSON.parse(Buffer.isBuffer(raw) ? raw.toString("utf8") : String(raw));
    } catch (e) {
        return undefined;
    }
}

function v2Unavailable(status, body) {
    if (status === 501 || status === 503) return true;
    if (status !== 404) return false;
    const detail = body && typeof body === "object" ? body.detail : body;
    if (detail === "Not Found") return true;
    return typeof detail === "string" && /v2|disabled/i.test(detail);
}

function items(body, key) {
    if (Array.isArray(body)) return body;
    if (body && Array.isArray(body.items)) return body.items;
    if (body && Array.isArray(body[key])) return body[key];
    return null;
}

function headers() {
    return {
        "Accept": "application/json",
        "X-Dev-User-Sub": String(env.get("LIMNOPULSE_DEV_USER_SUB") || "local-user-001"),
        "X-Dev-User-Email": String(env.get("LIMNOPULSE_DEV_USER_EMAIL") || "local@example.test"),
    };
}

const prefix = ctx.native ? "v2-native-" : "";
const body = parseBody(msg.payload);
if (v2Unavailable(msg.statusCode, body)) {
    return verdict(null, "v2-unavailable");
}
if (msg.statusCode !== 200) {
    return verdict(false, "v2-deployments-error-" + String(msg.statusCode));
}
const deployments = items(body, "deployments");
if (deployments === null) {
    return verdict(false, "v2-deployments-bad-body");
}

const tsMs = Date.parse(ctx.ts);
const matches = deployments.filter(function (d) {
    if (!d || d.component_id !== ctx.component_id) return false;
    const start = Date.parse(d.started_at);
    if (!Number.isFinite(start)) return false;
    const end = d.ended_at === null || d.ended_at === undefined ? Infinity : Date.parse(d.ended_at);
    return start <= tsMs && tsMs < end;
});

if (matches.length > 1) {
    return verdict(false, prefix + "overlapping-deployments");
}

let match = matches[0];
if (ctx.native) {
    if (match) {
        ctx.native_matches.push({
            component_id: ctx.component_id,
            deployment_id: match.deployment_id || null,
            asset_id: match.asset_id || null,
            ended: match.ended_at !== null && match.ended_at !== undefined,
        });
    }
    if (ctx.pending_component_ids.length > 0) {
        ctx.component_id = ctx.pending_component_ids.shift();
        msg.method = "GET";
        msg.url = ctx.base + "/v2/tenants/" + encodeURIComponent(ctx.tenant) +
            "/deployments?component_id=" + encodeURIComponent(ctx.component_id);
        msg.headers = headers();
        msg.payload = undefined;
        return [null, null, msg];
    }
    const assets = ctx.native_matches
        .map(function (m) { return m.asset_id; })
        .filter(function (a, i, all) { return all.indexOf(a) === i; });
    if (assets.length === 0) {
        return verdict(false, "v2-native-no-deployment-for-ts");
    }
    if (assets.length > 1) {
        return verdict(false, "v2-native-ambiguous-assets");
    }
    match = ctx.native_matches[0];
    ctx.component_id = match.component_id;
} else if (!match) {
    return verdict(false, "no-deployment-for-ts");
}

ctx.resolved_asset_id = match.asset_id || null;
ctx.deployment_id = match.deployment_id || null;
ctx.deployment_ended = ctx.native ? match.ended :
    match.ended_at !== null && match.ended_at !== undefined;
if (!ctx.resolved_asset_id) {
    return verdict(false, prefix + "deployment-without-asset");
}

msg.method = "GET";
msg.url = ctx.base + "/v2/tenants/" + encodeURIComponent(ctx.tenant) + "/assets/" +
    encodeURIComponent(ctx.resolved_asset_id);
msg.headers = headers();
msg.payload = undefined;
return [msg, null, null];

// Single output: verdict. Legacy devices: cross-checks the resolved asset
// against the deterministic legacy-pond asset id and the pond profile's
// legacy_pond_id. Native v2 devices: the resolved asset must exist; there is
// no /v1 pond to compare with, so expected_asset_id and v1_pond_id stay null.
const ctx = msg.e2e;

function verdict(ok, reason) {
    msg.payload = {
        device_id: ctx.device_id,
        seq: ctx.seq,
        ts: ctx.ts,
        v1_pond_id: ctx.v1_pond_id,
        resolved_asset_id: ctx.resolved_asset_id,
        expected_asset_id: ctx.expected_asset_id,
        ok: ok,
        reason: reason,
    };
    return msg;
}

// HTTP nodes return text; undefined = body is not JSON.
function parseBody(raw) {
    if (raw !== null && typeof raw === "object" && !Buffer.isBuffer(raw)) return raw;
    if (raw === undefined || raw === null) return undefined;
    try {
        return JSON.parse(Buffer.isBuffer(raw) ? raw.toString("utf8") : String(raw));
    } catch (e) {
        return undefined;
    }
}

function legacyPondId(asset) {
    if (!asset || typeof asset !== "object") return undefined;
    if (asset.legacy_pond_id !== undefined) return asset.legacy_pond_id;
    const candidates = [asset.profile, asset.pond_profile, asset.pond, asset.profiles && asset.profiles.pond];
    for (let i = 0; i < candidates.length; i++) {
        const p = candidates[i];
        if (p && typeof p === "object" && p.legacy_pond_id !== undefined) return p.legacy_pond_id;
    }
    return undefined;
}

const body = parseBody(msg.payload);
if (ctx.native) {
    if (msg.statusCode !== 200 || !body || typeof body !== "object") {
        return verdict(false, "v2-native-asset-lookup-error-" + String(msg.statusCode));
    }
    const assetId = body.asset_id || (body.asset && body.asset.asset_id);
    if (assetId !== ctx.resolved_asset_id) {
        return verdict(false, "v2-native-asset-mismatch");
    }
    return verdict(true, "v2-native");
}

if (msg.statusCode !== 200) {
    return verdict(false, "asset-lookup-error-" + String(msg.statusCode));
}
if (ctx.resolved_asset_id !== ctx.expected_asset_id) {
    // An ended deployment means the reading predates a relocation: the
    // expected asset (from the device's current /v1 pond) no longer applies.
    return verdict(false, ctx.deployment_ended ? "asset-mismatch-ended-deployment" : "asset-mismatch");
}
const legacy = legacyPondId(body);
if (legacy === undefined) {
    return verdict(false, "asset-without-legacy-pond-id");
}
if (legacy !== ctx.v1_pond_id) {
    return verdict(false, "legacy-pond-mismatch");
}
return verdict(true, "match");
